def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my_score = 0
    opp_score = 0
    opp_defects = 0
    for a, b in history:
        if b == 'D':
            opp_defects += 1
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    rounds_left = 100 - n
    last_me, last_opp = history[-1]
    opp_coops = n - opp_defects
    opp_rate = opp_coops / n

    recent_len = 10 if n >= 10 else n
    recent_start = n - recent_len
    recent_c = 0
    for i in range(recent_start, n):
        if history[i][1] == 'C':
            recent_c += 1
    recent_rate = recent_c / recent_len

    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_streak += 1
        else:
            break

    my_defects = 0
    for a, b in history:
        if a == 'D':
            my_defects += 1

    score_diff = my_score - opp_score

    # Aggressive punishment of chronic defectors
    if opp_rate <= 0.2:
        if rng.random() < 0.08 and rounds_left > 8:
            return 'C'
        return 'D'

    if defection_streak >= 4:
        if rng.random() < 0.12 and rounds_left > 5:
            return 'C'
        return 'D'

    # Last few rounds: exploit known cooperators
    if rounds_left <= 2:
        if last_opp == 'C' and recent_rate >= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if opp_rate >= 0.5:
            return 'D'
        return 'C'

    if rounds_left <= 6:
        if recent_rate >= 0.75:
            return 'C'
        if recent_rate <= 0.35:
            return 'D'
        if last_opp == 'D' and defection_streak >= 2:
            return 'D'
        if opp_rate >= 0.65:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    # Near-end mild exploitation of strong cooperators
    if rounds_left <= 12 and opp_rate >= 0.8 and recent_rate >= 0.7:
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    # Opponent almost never defects: cooperate, with rare probes
    if opp_defects == 0:
        if n >= 8 and n % 11 == 0 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Opponent mostly cooperates
    if opp_rate >= 0.85 and recent_rate >= 0.7:
        if last_opp == 'D':
            # rare defection from a nice opponent—likely noise or test; retaliate briefly
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        if coop_streak >= 8 and rng.random() < 0.07 and rounds_left > 15:
            return 'D'
        return 'C'

    if opp_rate >= 0.7 and recent_rate >= 0.5:
        if last_opp == 'D':
            if defection_streak >= 2:
                return 'D'
            return 'C' if rng.random() < 0.4 else 'D'
        return 'C'

    # Moderate / uncertain opponent: tit-for-tat with forgiveness and probing
    if last_opp == 'D':
        if defection_streak >= 3:
            if rng.random() < 0.65:
                return 'D'
            return 'C'
        if defection_streak == 2:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if recent_rate >= 0.55 and rng.random() < 0.55:
            return 'C'
        if score_diff <= -8:
            return 'D'
        return 'D' if rng.random() < 0.65 else 'C'

    # last_opp == 'C'
    if recent_rate >= 0.55:
        if my_defects > opp_defects + 3 and my_score < opp_score + 3:
            return 'C'
        if coop_streak >= 6 and rng.random() < 0.1 and rounds_left > 20:
            return 'D'
        return 'C'

    if recent_rate < 0.4:
        if score_diff < -5:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    return 'C'
